<section class="account-page"><div class="account-heading"><div><p class="eyebrow">SATICI MERKEZİ</p><h1>Ürün ve stok yönetimi</h1><p>Yalnızca kendi mağazanıza ait ürünleri ve dijital kod stoklarını yönetebilirsiniz.</p></div><a class="primary-link" href="<?= e(url('seller')) ?>">Satıcı paneli</a></div><form method="post" class="admin-form seller-product-form"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save_product"><input type="hidden" name="id" value="<?= (int)($editProduct['id']??0) ?>"><h2><?= $editProduct?'Ürünü düzenle':'Yeni ürün ekle' ?></h2><label>Ürün adı<input name="name" required minlength="3" maxlength="190" value="<?= e($editProduct['name']??'') ?>"></label><label>Kategori<select name="category_id" required><option value="">Kategori seçin</option><?php foreach($sellerCategories as $cat): ?><option value="<?= (int)$cat['id'] ?>" <?= (string)($editProduct['category_id']??'')===(string)$cat['id']?'selected':'' ?>><?= e($cat['name']) ?></option><?php endforeach; ?></select></label><label>Fiyat (₺)<input type="number" name="price" min="0" step="0.01" required value="<?= e($editProduct['price']??'') ?>"></label><label>Kısa açıklama<textarea name="short_description" rows="2"><?= e($editProduct['short_description']??'') ?></textarea></label><label>Ürün açıklaması<textarea name="description" rows="4"><?= e($editProduct['description']??'') ?></textarea></label><label>Görsel URL<input type="url" name="image" value="<?= e($editProduct['image']??'') ?>" placeholder="https://..."></label><label>Teslimat türü<select name="delivery_type"><option value="manual" <?= ($editProduct['delivery_type']??'manual')==='manual'?'selected':'' ?>>Manuel teslimat</option><option value="automatic" <?= ($editProduct['delivery_type']??'')==='automatic'?'selected':'' ?>>Otomatik dijital kod</option></select></label><label>Yayın durumu<select name="status"><option value="draft" <?= ($editProduct['status']??'draft')==='draft'?'selected':'' ?>>Taslak</option><option value="active" <?= ($editProduct['status']??'')==='active'?'selected':'' ?>>Yayında</option></select></label><div class="form-actions"><button type="submit">Ürünü kaydet</button><?php if($editProduct): ?><a href="<?= e(url('seller/products')) ?>">Vazgeç</a><?php endif; ?></div></form><div class="account-card"><h2>Ürünlerim</h2><div class="responsive-table"><table><thead><tr><th>Ürün</th><th>Fiyat</th><th>Teslimat</th><th>Durum</th><th>İşlem</th></tr></thead><tbody><?php foreach($sellerProducts as $p): ?><tr><td><?= e($p['name']) ?></td><td><?= number_format((float)$p['price'],2,',','.') ?> ₺</td><td><?= e($p['delivery_type']) ?></td><td><?= e($p['status']) ?></td><td><a href="<?= e(url('seller/products?edit='.(int)$p['id'])) ?>">Düzenle</a></td></tr><?php endforeach; ?><?php if(!$sellerProducts): ?><tr><td colspan="5">Henüz ürün eklemediniz.</td></tr><?php endif; ?></tbody></table></div></div><div class="account-card"><h2>Dijital kod stokları</h2><form method="post" class="account-form"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="import_codes"><label>Ürün<select name="product_id" required><option value="">Ürün seçin</option><?php foreach($sellerProducts as $p): ?><option value="<?= (int)$p['id'] ?>"><?= e($p['name']) ?></option><?php endforeach; ?></select></label><label>Kodlar (her satıra bir kod)<textarea name="codes" rows="6" required></textarea></label><button type="submit">Kodları güvenli şekilde ekle</button></form><div class="responsive-table"><table><thead><tr><th>Ürün</th><th>Hazır</th><th>Rezerve</th><th>Satıldı</th></tr></thead><tbody><?php foreach($sellerStock as $stock): ?><tr><td><?= e($stock['name']) ?></td><td><?= (int)$stock['available'] ?></td><td><?= (int)$stock['reserved'] ?></td><td><?= (int)$stock['sold'] ?></td></tr><?php endforeach; ?><?php if(!$sellerStock): ?><tr><td colspan="4">Stok kaydı bulunmuyor.</td></tr><?php endif; ?></tbody></table></div></div></section>